from __future__ import annotations

from ds.util.text import clean_f_str


def test_strips_indent_and_outer_blank_lines() -> None:
    name = "Mac"
    text = clean_f_str(
        f"""
        Hello {name}

        Rules:
        1. be nice
        """
    )
    assert text == "Hello Mac\n\nRules:\n1. be nice"


def test_multiline_value_leaves_indent_in() -> None:
    # documented caveat: a multi-line value's second line has no indent, so nothing is stripped
    schema = "a: Int64\nb: String"
    text = clean_f_str(
        f"""
        Schema:
        {schema}
        """
    )
    assert text.startswith("        Schema:")


def test_braces_left_alone() -> None:
    assert (
        clean_f_str("""
        {"a": 1}
        """)
        == '{"a": 1}'
    )
